BEGIN;
ALTER TABLE deck_words ADD COLUMN IF NOT EXISTS custom_meaning TEXT;
CREATE TABLE IF NOT EXISTS srs_cards(guild_id TEXT NOT NULL,user_id TEXT NOT NULL,entry_id BIGINT NOT NULL,repetition_count INTEGER NOT NULL DEFAULT 0,ease_factor DOUBLE PRECISION NOT NULL DEFAULT 2.5,interval_days INTEGER NOT NULL DEFAULT 0,due_at TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'NEW' CHECK(state IN('NEW','LEARNING','REVIEW','RELEARNING')),last_reviewed_at TEXT,review_count INTEGER NOT NULL DEFAULT 0,lapse_count INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(guild_id,user_id,entry_id));
CREATE INDEX IF NOT EXISTS idx_srs_due ON srs_cards(guild_id,user_id,due_at);
CREATE TABLE IF NOT EXISTS srs_sessions(id TEXT PRIMARY KEY,guild_id TEXT NOT NULL,user_id TEXT NOT NULL,deck_id BIGINT,deck_name TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('ACTIVE','PAUSED','COMPLETED')),queue_json TEXT NOT NULL,current_index INTEGER NOT NULL DEFAULT 0,revealed BOOLEAN NOT NULL DEFAULT FALSE,reviewed_count INTEGER NOT NULL DEFAULT 0,again_count INTEGER NOT NULL DEFAULT 0,hard_count INTEGER NOT NULL DEFAULT 0,good_count INTEGER NOT NULL DEFAULT 0,easy_count INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,completed_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS idx_srs_one_open ON srs_sessions(guild_id,user_id) WHERE status IN('ACTIVE','PAUSED');
CREATE TABLE IF NOT EXISTS srs_review_logs(id BIGSERIAL PRIMARY KEY,event_key TEXT NOT NULL UNIQUE,session_id TEXT NOT NULL REFERENCES srs_sessions(id) ON DELETE CASCADE,guild_id TEXT NOT NULL,user_id TEXT NOT NULL,entry_id BIGINT NOT NULL,rating TEXT NOT NULL CHECK(rating IN('AGAIN','HARD','GOOD','EASY')),was_new BOOLEAN NOT NULL,old_interval INTEGER NOT NULL,new_interval INTEGER NOT NULL,old_ease DOUBLE PRECISION NOT NULL,new_ease DOUBLE PRECISION NOT NULL,review_date TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(session_id,entry_id));
CREATE TABLE IF NOT EXISTS srs_settings(guild_id TEXT NOT NULL,user_id TEXT NOT NULL,new_per_day INTEGER NOT NULL DEFAULT 10 CHECK(new_per_day BETWEEN 0 AND 100),updated_at TEXT NOT NULL,PRIMARY KEY(guild_id,user_id));
INSERT INTO app_schema_migrations(version)VALUES(6)ON CONFLICT DO NOTHING;
ALTER TABLE srs_cards ENABLE ROW LEVEL SECURITY;ALTER TABLE srs_sessions ENABLE ROW LEVEL SECURITY;ALTER TABLE srs_review_logs ENABLE ROW LEVEL SECURITY;ALTER TABLE srs_settings ENABLE ROW LEVEL SECURITY;
COMMIT;
